import cv2, numpy as np

def clean_binary_mask(mask: np.ndarray, ksize: int = 5) -> np.ndarray:
    se = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (ksize, ksize))
    opened = cv2.morphologyEx(mask, cv2.MORPH_OPEN, se)
    return cv2.morphologyEx(opened, cv2.MORPH_CLOSE, se)

import cv2, numpy as np

def extract_bright_objects_uneven_bg(gray: np.ndarray) -> np.ndarray:
    se = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (17, 17))
    return cv2.morphologyEx(gray, cv2.MORPH_TOPHAT, se)
